changeSet.sql:
			update monad_academy.tasks
			set method_name = 'developerNamesBySalary',
				method_return_type = 'String',
				method_parameters = 'String[] developers',
				initial_code = 'class Solution {
    public String developerNamesBySalary(String[] developers) {

    }
}',
				solution_template = 'class Solution {
    public String developerNamesBySalary(String[] developers) {
        return java.util.Arrays.stream(developers)
               .map(value -> value.split(":"))
               .filter(parts -> "Dev".equals(parts[1]))
               .filter(parts -> Integer.parseInt(parts[2]) > 6000)
               .map(parts -> parts[0])
               .sorted()
               .collect(java.util.stream.Collectors.joining(","));
    }
}'
			where slug = 'developers-by-salary';

			update monad_academy.task_test_cases
			set input = 'new String[]{"Zoe:Dev:7000", "Adam:Dev:8000", "John:QA:9000"}',
				expected_output = 'Adam,Zoe'
			where task_id = (
				select id
				from monad_academy.tasks
				where slug = 'developers-by-salary'
			);
